import { readFileSync, writeFileSync } from "node:fs";
import { z } from "zod";
import { automationCommandSchema, automationSnapshotSchema, automationEventSchema, automationDraftSchema, ingestSchema, preferencesSchema, sourceFieldsSchema, alertParseSchema } from "../lib/automation";

// Workspace schemas are generated by generate-api-v3.ts first; automation shapes come from runtime.
const spec = JSON.parse(readFileSync("docs/API-V3.openapi.json", "utf8"));
const schema = (value: z.ZodType) => {
  const { $schema: dialect, ...document } = z.toJSONSchema(value);
  void dialect;
  return document;
};
const reference = (name: string) => ({ $ref: `#/components/schemas/${name}` });
const jsonContent = (value: unknown) => ({ "application/json": { schema: value } });
const error = { description: "Safe JSON error. Inspect error.code before retrying; 409 can mean revision, idempotency, duplicate review, source pause or archive conflict.", content: jsonContent({ type: "object", required: ["error"], properties: { error: { type: "object", required: ["code", "message"], properties: { code: { type: "string" }, message: { type: "string" } } } } }) };
const failures = Object.fromEntries([400, 401, 403, 404, 409, 413, 415, 503].map(status => [String(status), error]));
const success = (value: unknown, description: string) => ({ description, content: jsonContent(value) });
const body = (value: unknown) => ({ required: true, content: jsonContent(value) });
const id = z.string().regex(/^[A-Za-z0-9_-]{1,80}$/);
const envelope = z.object({ expectedRevision: z.number().int().min(0).max(Number.MAX_SAFE_INTEGER), requestId: id, command: automationCommandSchema }).strict();
const previewOutput = z.object({ draft: automationDraftSchema, reference: z.string(), issues: z.array(z.string()) });
const tokenMetadata = z.object({ id: z.string(), name: z.string(), scopes: z.array(z.enum(["finance:read", "finance:write"])), expiresAt: z.string(), revokedAt: z.string().nullable(), createdAt: z.string() });
const tokenCreate = z.object({ name: z.string().min(1).max(80), scopes: z.array(z.enum(["finance:read", "finance:write"])).min(1).max(2), expiresInDays: z.number().int().min(1).max(365) }).strict();
Object.assign(spec.components.schemas, {
  AutomationCommand: schema(automationCommandSchema), AutomationSnapshot: schema(automationSnapshotSchema),
  AutomationEvent: schema(automationEventSchema), AutomationDraft: schema(automationDraftSchema),
  WorkspacePreferences: schema(preferencesSchema), AutomationSourceInput: schema(sourceFieldsSchema),
  IngestInput: schema(ingestSchema), AutomationEnvelope: schema(envelope), AlertPreviewInput: schema(alertParseSchema),
  AlertPreview: schema(previewOutput), TokenMetadata: schema(tokenMetadata), TokenCreateInput: schema(tokenCreate),
});
spec.info.title = "Budget Go Finance & Automation API";
spec.info.version = "3.2.0";
spec.info.description += " Bangladesh automation stages owned SMS/email/manual alerts for review. It does not connect to a bank or auto-post incoming messages. Raw-message retention defaults off; saving it off purges retained text while preserving derived drafts. OTP/security patterns are rejected. Stable source/external IDs protect delivery retries; accepting an event atomically links one financial transaction. No OAuth discovery is provided.";
spec.tags = [{ name: "Workspace" }, { name: "Automation" }, { name: "Credentials" }, { name: "MCP" }];
for (const operation of Object.values(spec.paths["/api/v3/workspace"]) as Record<string, unknown>[]) operation.tags = ["Workspace"];
spec.paths["/api/v3/automation"] = {
  get: { tags: ["Automation"], operationId: "getAutomation", summary: "Read owned preferences, sources and one inbox page", description: "Requires finance:read. Returns up to 200 events plus eventTotal and nextCursor. Follow the owned cursor for subsequent pages. Not a full inbox export. No financial writes.", parameters: [{ in: "query", name: "cursor", required: false, description: "Owned event ID returned as nextCursor from the preceding page.", schema: schema(id) }], responses: { "200": success(reference("AutomationSnapshot"), "Owned automation snapshot; nextCursor is null at the end."), ...failures } },
  post: { tags: ["Automation"], operationId: "mutateAutomation", summary: "Update preferences/sources or review an inbox event", description: "Requires finance:write and current shared revision. New commands use fresh requestId; after an unknown outcome replay the identical envelope. event_accept requires a complete valid reviewed draft and explicit duplicate acknowledgement when a candidate exists. Transaction creation, provenance link, revision and receipt are atomic. Accepted events cannot produce another entry; edit the financial entry instead. Saving raw retention off purges stored raw inbox text.", requestBody: body(reference("AutomationEnvelope")), responses: { "200": success(reference("AutomationSnapshot"), "Current saved automation snapshot after the command or exact replay."), ...failures } },
};
spec.paths["/api/v3/ingest"] = { post: { tags: ["Automation"], operationId: "ingestAlert", summary: "Idempotently stage an alert without posting money", description: "Requires finance:write and enabled automation/source. Supply rawText or a structured partial draft. Explicit draft fields override conservative parser fields; missing/ambiguous values require review. All IDs are same-owner references. Same source/externalId/body returns existing event; changed body returns409. No expectedRevision is required for ingestion. Source/automation pause is enforced even on replay; reads can inspect the saved event. Maximum 100 sources, 2000 events and 16000 raw text characters per event.", requestBody: body(reference("IngestInput")), responses: { "200": success({ type: "object", required: ["revision", "event", "replayed"], properties: { revision: { type: "integer", minimum: 0, maximum: Number.MAX_SAFE_INTEGER }, event: reference("AutomationEvent"), replayed: { type: "boolean" } } }, "Staged or replayed event. No transaction has been posted."), ...failures } } };
spec.paths["/api/v3/automation/parse"] = { post: { tags: ["Automation"], operationId: "parseAlert", summary: "Preview conservative Bangladesh alert extraction", description: "Requires finance:read; cookie requests still require the configured Origin for this POST. Does not create an event or transaction. Recognized OTP/security text is rejected. Bengali digits normalize; explicit unambiguous BDT amounts and four-digit-year dates can be extracted. Missing fields remain null for review.", requestBody: body(reference("AlertPreviewInput")), responses: { "200": success(reference("AlertPreview"), "Candidate extraction, not a posting guarantee or bank authentication."), ...failures } } };
const sessionOnly = [{ SessionCookie: [] }];
spec.paths["/api/v1/tokens"] = {
  get: { tags: ["Credentials"], operationId: "listIntegrationTokens", security: sessionOnly, summary: "List owned token metadata (browser session only)", responses: { "200": success({ type: "array", items: reference("TokenMetadata") }, "Metadata only; no token secrets."), ...failures } },
  post: { tags: ["Credentials"], operationId: "createIntegrationToken", security: sessionOnly, summary: "Create a named expiring token (browser session only)", description: "finance:read scope is required; finance:write optional. Unique scopes only. Name has no surrounding spaces. At most50 active tokens. Returned secret is shown once; store privately. Bearer callers cannot manage credentials.", requestBody: body(reference("TokenCreateInput")), responses: { "201": success({ type: "object", required: ["token", "metadata"], properties: { token: { type: "string", description: "Sensitive one-time response secret; never log or commit.", "x-sensitive": true }, metadata: reference("TokenMetadata") } }, "One-time secret plus metadata. Never log or commit it."), ...failures } },
};
spec.paths["/api/v1/tokens/{id}"] = { delete: { tags: ["Credentials"], operationId: "revokeIntegrationToken", security: sessionOnly, summary: "Revoke an owned token (browser session only)", parameters: [{ in: "path", name: "id", required: true, schema: { type: "string" } }], responses: { "200": success({ type: "object", required: ["revoked"], properties: { revoked: { const: true } } }, "Token revoked; dependent automations lose access."), ...failures } } };
spec.paths["/api/mcp"] = { post: { tags: ["MCP"], operationId: "callMcpTransport", summary: "Official MCP SDK Streamable HTTP endpoint", description: "MCP protocol endpoint, not a normal REST command envelope. Initialize and use tools/list/tools/call with an MCP client. Current tools: workspace_get, workspace_mutate, automation_get, automation_mutate, alert_ingest, alert_parse, plus11 legacy finance tools. Tool failures are returned with isError and safe error content. Manual bearer auth; no OAuth discovery. Mutation schemas/semantics match the REST services.", requestBody: body({ type: "object", description: "MCP JSON-RPC protocol request; official SDK owns the transport schema." }), responses: { "200": success({ description: "Official MCP protocol result or notification response; inspect tool isError." }, "MCP protocol response; transport success alone does not confirm a financial write."), "202": { description: "MCP notification accepted where applicable." }, ...failures } } };
writeFileSync("docs/API.openapi.json", JSON.stringify(spec, null, 2) + "\n");
console.log("Generated docs/API.openapi.json from runtime workspace and automation schemas plus existing token/MCP contracts.");
